import app from 'flarum/forum/app';
import Link from 'flarum/common/components/Link';

/**
 * Types and helpers shared by CharactersTab/ActivityTab/ArenaTab. Split out
 * of the old single 999-line StatsTabs.tsx so each tab can be read and
 * changed in isolation.
 */

export function cacheBust() {
  return Date.now();
}
export function invalidateHomeSliderCache() {
  if (typeof window === 'undefined') return;
  try {
    window.dispatchEvent(new Event('rolevaya:invalidate-home-slider-cache'));
  } catch (_unused) {}
}
export function apiUrl(path) {
  const base = app.forum.attribute('apiUrl');
  return base.replace(/\/$/, '') + path;
}
export function forumBaseUrl() {
  const base = app.forum.attribute('baseUrl') || '';
  return base.replace(/\/$/, '');
}
export function playerName(row) {
  return row.nickname || row.username || "#".concat(row.user_id);
}
export function formatNumber(value) {
  return new Intl.NumberFormat('ru-RU').format(Number(value) || 0);
}
export function userProfilePath(userId, username) {
  const user = app.store.getById('users', String(userId));
  if (user) {
    try {
      const routed = app.route.user(user);
      if (routed && typeof routed === 'string') return routed;
    } catch (_unused2) {}
    const profileUrl = user.attribute('profileUrl') || user.attribute('url') || null;
    if (profileUrl && String(profileUrl).trim()) {
      return profileUrl;
    }
    const slug = user.attribute('slug') || user.attribute('username') || username || null;
    if (slug && String(slug).trim()) {
      return "/u/".concat(slug);
    }
  }
  const fallbackSlug = (username || '').trim();
  if (fallbackSlug) return "/u/".concat(fallbackSlug);
  return "/u/".concat(userId);
}
export function userLink(userId, label, username) {
  return m(Link, {
    className: "RolevayaPlayerLink",
    href: userProfilePath(userId, username),
    title: label
  }, label);
}
export function avatarUrl(row) {
  const raw = (row.avatar_url || '').trim();
  if (raw) {
    if (/^(data:|blob:)/i.test(raw)) return raw;
    if (/^https?:\/\//i.test(raw)) return raw;
    const base = forumBaseUrl();
    if (raw.startsWith('/')) return "".concat(base).concat(raw);
    return "".concat(base, "/assets/avatars/").concat(raw);
  }
  const userId = row.user_id;
  if (!userId) return null;
  const user = app.store.getById('users', String(userId));
  const storeUrl = (user == null ? void 0 : user.attribute('avatarUrl')) || null;
  return storeUrl && String(storeUrl).trim() ? storeUrl : null;
}
export function rankClass(i) {
  const suffix = i === 0 ? '1' : i === 1 ? '2' : i === 2 ? '3' : i === 3 ? '4' : '';
  return 'RolevayaRank ' + (suffix ? "RolevayaRank--".concat(suffix) : '');
}

// Shared across all three tabs so the same user isn't fetched twice just
// because they show up on e.g. both the activity and arena leaderboards.
const ensuredUserIds = new Set();

// IDs that have been requested but not yet fetched. When StatsTabs mounts all
// three tabs at once, each calls ensureUsersLoaded() as soon as its own data
// loads; a plain boolean "inflight" guard used to make the second/third call
// bail out immediately, dropping any user IDs unique to those tabs. Now every
// call merges its IDs into this pending set, and whichever call is already
// running drains the set in a loop until it's empty — so IDs added while a
// fetch is in progress still get picked up before the run finishes, instead
// of being silently skipped.
const pendingUserIds = new Set();
let inflightRun = null;
export async function ensureUsersLoaded(userIds) {
  const ids = Array.from(new Set(userIds)).filter(id => id && !ensuredUserIds.has(id) && !app.store.getById('users', String(id)));
  ids.forEach(id => pendingUserIds.add(id));
  if (!pendingUserIds.size) return;
  if (inflightRun) {
    await inflightRun;
    return;
  }
  inflightRun = (async () => {
    try {
      // Flarum's /api/users list endpoint has no real "fetch exactly these
      // IDs" filter and also requires the searchUsers permission (often
      // denied to guests), so this used to mean one GET /api/users/{id}
      // request per user — up to ~13 sequential round-trips (batched 4 at a
      // time) to hydrate a full 50-row leaderboard. /rolevaya/users (see
      // ListRolevayaUsersController) accepts a comma-separated id list and
      // returns all of them as a single JSON:API response, so one request
      // per (up to 200-id) batch is enough; pushPayload() then stores them
      // exactly like app.store.find('users', id) would.
      //
      // Re-check pendingUserIds.size on every iteration (not just once up
      // front): a concurrent tab's ensureUsersLoaded() call can add more IDs
      // to the set while this loop is awaiting a batch, and those need to be
      // drained too before this run finishes.
      while (pendingUserIds.size) {
        const batch = Array.from(pendingUserIds).slice(0, 200);
        batch.forEach(id => {
          pendingUserIds.delete(id);
          ensuredUserIds.add(id);
        });
        try {
          const res = await app.request({
            method: 'GET',
            url: apiUrl('/rolevaya/users'),
            params: {
              ids: batch.join(',')
            }
          });
          app.store.pushPayload(res);
        } catch (_unused3) {
          // A failed batch just means those rows render without a hydrated
          // User model this time around (falling back to the raw
          // username/nickname already present on the leaderboard row).
        }
        m.redraw();
      }
    } finally {
      inflightRun = null;
    }
  })();
  await inflightRun;
}
flarum.reg.add('forumaker-rolevaya', 'forum/components/stats/statsShared', { cacheBust: cacheBust,invalidateHomeSliderCache: invalidateHomeSliderCache,apiUrl: apiUrl,forumBaseUrl: forumBaseUrl,playerName: playerName,formatNumber: formatNumber,userProfilePath: userProfilePath,userLink: userLink,avatarUrl: avatarUrl,rankClass: rankClass, });